CREATE OR REPLACE FUNCTION public.get_user_role()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_role_name text;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT r.role_name INTO v_role_name
  FROM public.profiles p
  JOIN public.role r ON p.role_id = r.role_id
  WHERE p.id = auth.uid();

  RETURN v_role_name;
END;
$function$
